import {people} from './data.js';
const themes=['Identity continuity','First-day readiness','Remote onboarding','Shared-device access','Access governance','Offboarding evidence'];
export function homePage(){return `<div class="home-shell"><header class="home-header"><a href="#home" aria-label="MajorKey workshop home"><img src="./assets/majorkey-logo.svg" alt="MajorKey" width="180" height="32"></a><span>IDENTITY IN ACTION</span><button class="quiet" data-action="agenda">Workshop agenda ↗</button></header><main class="home-main"><div class="home-section-heading"><h2>Choose your persona</h2><span>Choose a persona → Story → Architecture → Live demo</span></div><section class="home-personas" aria-label="Choose a persona">${people.map((p,i)=>`<article class="home-persona" style="--persona-tone:${['#20f593','#c398ff','#77ddcb','#b9b1ff','#f0c994','#83c5ff'][i]}"><div class="home-card-top"><span class="home-avatar">${p.initials}</span><span class="home-topic">${themes[i]}</span><span class="home-card-arrow" aria-hidden="true">↗</span></div><h3>${p.name}</h3><div class="home-job">${p.job}</div><h4>${p.role}</h4><p>${p.intro}</p><div class="home-card-foot"><span>${p.moments.length} story moments</span></div><div class="home-card-actions"><button class="primary" data-action="person" data-value="${i}">Explore story →</button><button class="outline" data-action="person-ai" data-value="${i}">✦ How AI helps</button></div></article>`).join('')}</section><footer class="home-footer"><span>MajorKey · Harborline reference lab</span><div><button class="quiet" data-action="catalog">Browse 34 use cases</button><button class="quiet" data-action="ready">Presenter preparation</button></div></footer></main></div><dialog id="modal" aria-labelledby="modal-title"></dialog>`;}
